## Row Filter # `1575`
# Node state: `CONFIGURED`
# Input: [Port 1] 1557:1 from Column Filter #1557
# Output: [Port 1] 1575:1 to 1586 CSV Writer #1586
# https://hub.knime.com/knime/extensions/org.knime.features.base/latest/org.knime.base.node.preproc.filter.row3.RowFilterNodeFactory
df = context['1557:1']  # input table
def _rf_norm_name(s):
    return _re.sub(r'[^a-z0-9]+', '', str(s).lower())
_RF_LCMAP = {c.lower(): c for c in df.columns}
_RF_NORMMAP = {_rf_norm_name(c): c for c in df.columns}

def _rf_resolve(name):
    if name in df.columns:
        return name
    if name is None:
        return None
    c = _RF_LCMAP.get(str(name).lower())
    if c is not None:
        return c
    key = _rf_norm_name(name)
    c = _RF_NORMMAP.get(key)
    if c is not None:
        return c
    # Heuristic aliases for common aggregate column names
    if key in {'occurrencecount','count','rowcount'}:
        cand = [col for col in df.columns if 'count' in _rf_norm_name(col)]
        if len(cand) == 1:
            return cand[0]
    return None

def _rf_to_num(val):
    s = pd.Series([val])
    v = pd.to_numeric(s, errors='coerce').iloc[0]
    return v

mask = pd.Series(True, index=df.index)
_col0 = _rf_resolve('Applications_log10')
if _col0 is None:
    _c0 = pd.Series(True, index=df.index)  # missing column → neutral
else:
    _s0 = df[_col0]
    _c0 = pd.to_numeric(_s0, errors='coerce') > _rf_to_num('1.0')
mask = (mask & _c0)
_invert = False
final_mask = (~mask) if _invert else mask
out_df = df[final_mask].copy()
context['1575:1'] = out_df

